"""Loads the cue-conflict images generated by make_cue_conflicts.py, along
with each image's content (shape) and style (texture) class labels, for
evaluation in run_task1_shape_texture.py.
"""
from __future__ import annotations

import json
from pathlib import Path

from PIL import Image
from torch.utils.data import Dataset


class CueConflictDataset(Dataset):
    def __init__(self, manifest_path: str, images_dir: str):
        record = json.loads(Path(manifest_path).read_text())
        self.images_dir = Path(images_dir)
        self.items = record["images"]
        self.class_pairs = record["class_pairs"]

    def __len__(self):
        return len(self.items)

    def __getitem__(self, i: int):
        item = self.items[i]
        img = Image.open(self.images_dir / item["filename"]).convert("RGB")
        return img, item["content_label"], item["style_label"], item["filename"]
